    @Test void combinedPackMarksFarmReadyButDeclineKeepsSeparateManualFarmPack(){var city=city();farm.ready.clear();var id=kr.minecraft.survival.citytextures.CityTexturesPlugin.PACK_ID;server.getPluginManager().callEvent(new PlayerResourcePackStatusEvent(player,id,PlayerResourcePackStatusEvent.Status.ACCEPTED));assertFalse(farm.ready.contains(player.getUniqueId()));server.getPluginManager().callEvent(new PlayerResourcePackStatusEvent(player,id,PlayerResourcePackStatusEvent.Status.SUCCESSFULLY_LOADED));assertTrue(farm.ready.contains(player.getUniqueId()));server.getPluginManager().callEvent(new PlayerResourcePackStatusEvent(player,id,PlayerResourcePackStatusEvent.Status.DECLINED));assertFalse(farm.ready.contains(player.getUniqueId()));server.dispatchCommand(player,"농사 팩확인");server.getPluginManager().callEvent(new PlayerResourcePackStatusEvent(player,id,PlayerResourcePackStatusEvent.Status.SUCCESSFULLY_LOADED));server.getPluginManager().callEvent(new PlayerResourcePackStatusEvent(player,id,PlayerResourcePackStatusEvent.Status.FAILED_DOWNLOAD));assertTrue(farm.ready.contains(player.getUniqueId()));assertTrue(player.isOnline());}
    @Test void manualCitySettingDoesNotPretendThatOldCityPackHasNewUiIcons(){var city=city();server.dispatchCommand(player,"도시팩 켜기");farm.setMenuPackReady(player,false);assertFalse(farm.menuReady.contains(player.getUniqueId()));server.dispatchCommand(player,"도시팩 메뉴켜기");assertTrue(farm.menuReady.contains(player.getUniqueId()));server.dispatchCommand(player,"도시팩 끄기");assertFalse(farm.menuReady.contains(player.getUniqueId()));}
    void snapshot(Map<String,Object> screens,String key){Inventory inv=player.getOpenInventory().getTopInventory();List<Object> slots=new ArrayList<>();for(int i=0;i<54;i++){var item=inv.getItem(i);if(item==null){slots.add(null);continue;}var meta=item.getItemMeta();Map<String,Object> entry=new LinkedHashMap<>();entry.put("material",item.getType().name());entry.put("name",meta.hasDisplayName()?meta.getDisplayName():"");entry.put("lore",meta.getLore()==null?List.of():meta.getLore());entry.put("model",meta.getItemModel()==null?null:meta.getItemModel().toString());entry.put("glow",meta.hasEnchantmentGlintOverride()&&Boolean.TRUE.equals(meta.getEnchantmentGlintOverride()));slots.add(entry);}screens.put(key,Map.of("title",player.getOpenInventory().getTitle(),"slots",slots));}
    @Test void realMenusGenerateUiSnapshotsAndKeepModelsOnlyInsideOwnedScreens()throws Exception{var menu=MockBukkit.loadWith(kr.minecraft.survival.menu.KoreanMenuPlugin.class,root.resolve("korean-menu/src/main/resources/plugin.yml").toFile());server.getPluginManager().addPermissions(menu.getDescription().getPermissions());var codex=MockBukkit.loadWith(kr.minecraft.survival.codex.KoreanCodexPlugin.class,root.resolve("korean-codex/src/main/resources/plugin.yml").toFile());server.getPluginManager().addPermissions(codex.getDescription().getPermissions());var city=city();server.getPluginManager().callEvent(new PlayerResourcePackStatusEvent(player,kr.minecraft.survival.citytextures.CityTexturesPlugin.PACK_ID,PlayerResourcePackStatusEvent.Status.SUCCESSFULLY_LOADED));player.getInventory().setItem(0,new ItemStack(Material.OAK_LOG,3));Map<String,Object> screens=new LinkedHashMap<>();menu.openFromNavigation(player);server.getScheduler().performTicks(3);assertEquals("tycoon:ui/codex",player.getOpenInventory().getTopInventory().getItem(20).getItemMeta().getItemModel().toString());assertTrue(player.getOpenInventory().getTopInventory().getItem(20).getItemMeta().getLore().getFirst().contains("등록 가능 1종"));snapshot(screens,"main");click(20);snapshot(screens,"codex");assertEquals("tycoon:ui/forest",player.getOpenInventory().getTopInventory().getItem(10).getItemMeta().getItemModel().toString());click(10);snapshot(screens,"category");assertNull(player.getOpenInventory().getTopInventory().getItem(10).getItemMeta().getItemModel());click(10);snapshot(screens,"confirmation");click(30);assertEquals(2,player.getInventory().getItem(0).getAmount());snapshot(screens,"registered");server.dispatchCommand(player,"업적");server.getScheduler().performTicks(3);snapshot(screens,"achievements");server.dispatchCommand(player,"도감효과");server.getScheduler().performTicks(3);snapshot(screens,"effects");click(47);assertTrue(player.getOpenInventory().getTitle().contains("마을 수첩"));assertEquals(2,player.getInventory().getItem(0).getAmount());assertNull(player.getInventory().getItem(0).getItemMeta().getItemModel());Path output=root.resolve("interface-resourcepack/build/snapshots.json");Files.createDirectories(output.getParent());Files.writeString(output,new com.google.gson.Gson().toJson(screens));}

    @Test void joiningWithUiBridgeRequestsOneCombinedPackInsteadOfTwo()throws Exception{var city=city();var file=new java.io.File(city.getDataFolder(),"ui.yml");var config=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(file);config.set("팩-주소","https://example.com/menu.zip");config.set("체크섬-SHA1","a".repeat(40));config.save(file);server.dispatchCommand(server.getConsoleSender(),"도시팩 새로고침");farm.getConfig().set("리소스팩.접속시-요청",true);assertTrue(city.isMenuPackAutoEnabled(player));server.getPluginManager().callEvent(new PlayerJoinEvent(player,""));server.getScheduler().performTicks(61);assertEquals(1,player.packRequests);assertEquals(kr.minecraft.survival.citytextures.CityTexturesPlugin.PACK_ID,player.packId);}


